async fn r2101000_get_api_matches_id_ranks_carries_each_seat_s_win_streak() {
    let Routed { app, token_a, .. } = routed().await;
    put_rank(&app, merged(json_of(&fresh_rank(&season(), A, 0)), json!({ "games": 4, "wins": 4, "streak": 4 }))).await;
